SELECT analytics_order_facts.channel, SUM(analytics_order_facts.contribution_margin) / CAST(NULLIF(SUM(analytics_order_facts.net_revenue), 0) AS DECIMAL) AS contribution_margin_pct FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 10 AND analytics_order_facts.region = 'East' AND analytics_order_facts.customer_segment = 'education' AND analytics_order_facts.category = 'category_10' AND analytics_order_facts.payment_method = 'bank_transfer' GROUP BY analytics_order_facts.channel ORDER BY contribution_margin_pct DESC, analytics_order_facts.channel ASC LIMIT 12
